BEGIN
    -- WORM append-only: 仅 INSERT 允许, UPDATE/DELETE 触发异常
    IF (TG_OP = 'UPDATE' OR TG_OP = 'DELETE') THEN
        RAISE EXCEPTION 'agent_session_audit is WORM append-only (per 守门 #13 d + ADR-0043)';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

