-- ==========================================
-- 7.WORM  WORM append-only audit trigger (per 守门 #13 d + ADR-0043)
-- 仅允许 INSERT, UPDATE/DELETE 触发异常
-- ==========================================
CREATE OR REPLACE FUNCTION gamify_xp_history_worm_trigger() RETURNS TRIGGER AS $$
BEGIN
    -- WORM append-only: 仅 INSERT 允许, UPDATE/DELETE 触发异常
    IF (TG_OP = 'UPDATE' OR TG_OP = 'DELETE') THEN
        RAISE EXCEPTION 'gamify_xp_history is WORM append-only (per 守门 #13 d + ADR-0043)';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_gamify_xp_history_worm ON gamify_xp_history;
CREATE TRIGGER trg_gamify_xp_history_worm
    BEFORE UPDATE OR DELETE ON gamify_xp_history
    FOR EACH ROW
    EXECUTE FUNCTION gamify_xp_history_worm_trigger();

COMMIT;

